## Task 5: Create Modal Control Functions
**File:** `server/templates/client.html`
**Location:** JavaScript section (around line 677, replacing runScript)
**What to create:** Three new functions for modal management
**Dependencies:** Task 1 (HTML structure)
**Approach:**

### 5a: showScriptConfirmationModal function
```javascript
function showScriptConfirmationModal(clientId, scriptId, scriptLabel, scriptDescription, requireConfirm) {
    // Store current script info in global variables
    window._currentScript = { clientId, scriptId, scriptLabel, requireConfirm };

    // Update modal content
    document.getElementById('script-modal-title').textContent = 'Run Script: ' + scriptLabel;
    var descEl = document.getElementById('script-modal-description');
    if (scriptDescription) {
        descEl.textContent = scriptDescription;
        descEl.style.display = 'block';
    } else {
        descEl.style.display = 'none';
    }

    // Clear previous context and errors
    document.getElementById('script-context-input').value = '';
    document.getElementById('script-modal-error').style.display = 'none';

    // Show modal and focus context input
    document.getElementById('script-confirmation-modal').classList.add('active');
    document.getElementById('script-context-input').focus();
}
```

### 5b: closeScriptConfirmationModal function
```javascript
function closeScriptConfirmationModal(event) {
    if (!event || event.target === document.getElementById('script-confirmation-modal')) {
        document.getElementById('script-confirmation-modal').classList.remove('active');
        window._currentScript = null;
    }
}
```

### 5c: confirmRunScript function
```javascript
function confirmRunScript() {
    if (!window._currentScript) return;

    var context = document.getElementById('script-context-input').value || '';
    var script = window._currentScript;

    // Show loading state
    var runBtn = document.getElementById('script-run-button');
    runBtn.textContent = 'Running...';
    runBtn.disabled = true;

    // Make API call (preserve existing logic)
    fetch('/api/clients/' + encodeURIComponent(script.clientId) + '/run-script?key=' + encodeURIComponent(_dashKey), {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({
            script_id: script.scriptId,
            context: context
        })
    }).then(function(resp) {
        if (!resp.ok) {
            throw new Error('Failed to run script');
        }
        // Success - close modal and refresh
        closeScriptConfirmationModal();
        refreshScripts();
    }).catch(function(error) {
        // Show error in modal instead of alert
        document.getElementById('script-modal-error').textContent = error.message || 'Failed to run script';
        document.getElementById('script-modal-error').style.display = 'block';
    }).finally(function() {
        // Reset button state
        runBtn.textContent = 'Run Script';
        runBtn.disabled = false;
    });
}
```

## Task 6: Add Keyboard Navigation Support
**File:** `server/templates/client.html`
**Location:** JavaScript section, after modal functions
**What to create:** Event listeners for keyboard shortcuts
**Dependencies:** Task 5 (modal functions)
**Approach:**
- Add keydown event listener to script-confirmation-modal
- Support Enter key to submit (call confirmRunScript)
- Support Escape key to cancel (call closeScriptConfirmationModal)
- Ensure proper focus management

```javascript
// Add to modal HTML or via addEventListener
document.getElementById('script-confirmation-modal').addEventListener('keydown', function(e) {
    if (e.key === 'Escape') {
        closeScriptConfirmationModal();
    } else if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) {
        confirmRunScript();
    }
});
```

